function icon(name){return `<svg class="icon" viewBox="0 0 24 24">${icons[name]||icons.grid}</svg>`}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function initials(name='User'){return name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function route(){return location.hash.slice(1)||'home'}
function money(v){return v===0?'Free':`$${v}`}
function date(v){return new Date(v).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}
function toast(message){const e=document.createElement('div');e.className='toast';e.textContent=message;document.body.appendChild(e);setTimeout(()=>e.remove(),2600)}
function modal(title,body){const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="close">${icon('x')}</button></div>${body}</div>`;document.body.appendChild(wrap);wrap.querySelector('.close').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};return wrap}
async function api(path,options={}){
  const headers={...(options.headers||{})};
  if(options.body && !headers['Content-Type']) headers['Content-Type']='application/json';
  if(token) headers.Authorization=`Bearer ${token}`;
  const res=await fetch(`/api${path}`,{...options,headers});
  const data=await res.json().catch(()=>({}));
  if(res.status===401 && token){token='';me=null;localStorage.removeItem(TOKEN_KEY);location.hash='login'}
  if(!res.ok) throw new Error(data.error||'Something went wrong.');
  return data;
}
function setToken(value){token=value||'';if(token)localStorage.setItem(TOKEN_KEY,token);else localStorage.removeItem(TOKEN_KEY)}
async function loadMe(){if(!token){me=null;return}try{me=(await api('/me')).user}catch{me=null}}


