const CAREER_TASK_KEY='coursepilot_career_tasks';
const CAREER_COMPANIES=['Google','Microsoft','Amazon','IBM','Oracle','SAP','Accenture','Deloitte'];
function careerProfile(course={}){
  const text=`${course.title||''} ${course.category||''} ${(course.skills||[]).join(' ')}`.toLowerCase();
  if(/tensorflow|machine learning|llm|rag|agentic|ai |robot/.test(text)) return {
    roles:['AI / ML Engineer','AI Automation Developer','Junior Machine Learning Engineer'],
    project:'Build an AI application with a usable interface, evaluation notes and a documented deployment.',
    value:'Shows practical AI application skills, model or agent workflow understanding, and the ability to turn AI concepts into a working product.'
  };
  if(/aws|docker|kubernetes|devops|linux|cloud|reliability/.test(text)) return {
    roles:['Cloud Engineer','DevOps Engineer','Site Reliability / Platform Engineer'],
    project:'Deploy a production-style web service with CI/CD, environment configuration, monitoring notes and a clear architecture diagram.',
    value:'Demonstrates cloud, deployment and reliability skills that support modern software delivery teams.'
  };
  if(/testing|qa|unit testing|integration testing|maintenance|issue resolution/.test(text)) return {
    roles:['QA Automation Engineer','Software Test Engineer','Application Support Engineer'],
    project:'Create a tested application with unit and integration coverage, a bug log and a short maintenance runbook.',
    value:'Demonstrates quality, troubleshooting and reliability habits that employers expect in production software teams.'
  };
  if(/spring|java|django|flask|php|node|express|api|backend/.test(text)) return {
    roles:['Backend Developer','API Developer','Software Engineer'],
    project:'Build and document a secure REST API with authentication, validation, persistent data and automated tests.',
    value:'Shows backend engineering, API design and application-security skills that transfer directly to web and software roles.'
  };
  if(/react|redux|bootstrap|next|typescript|frontend/.test(text)) return {
    roles:['Front-End Developer','React Developer','UI Engineer'],
    project:'Build a responsive production-style frontend that consumes an API, handles loading/error states and includes accessibility checks.',
    value:'Shows modern frontend development, component architecture and user-interface implementation skills.'
  };
  if(/sql|sqlite|mongo|database/.test(text)) return {
    roles:['Database Developer','Backend Developer','Junior Data Engineer'],
    project:'Design a small data-backed application with a clear schema, queries, indexes and an API or reporting layer.',
    value:'Demonstrates practical data modelling and persistence skills used in backend and data-focused roles.'
  };
  if(/data structure|algorithm|system design|computer science/.test(text)) return {
    roles:['Software Engineer','Graduate Software Developer','Full-Stack Developer'],
    project:'Create a documented engineering project that explains algorithm choices, architecture trade-offs and performance decisions.',
    value:'Strengthens problem-solving and engineering fundamentals used in technical interviews and day-to-day software work.'
  };
  return {
    roles:['Full-Stack Developer','Web Developer','Software Engineer'],
    project:'Build an end-to-end portfolio project with a responsive frontend, API, persistent data, testing and deployment documentation.',
    value:'Demonstrates an end-to-end understanding of building, testing and shipping a working software product.'
  };
}
function careerTasks(){try{return JSON.parse(localStorage.getItem(CAREER_TASK_KEY)||'{}')}catch{return {}}}
function setCareerTask(key,value){const tasks=careerTasks();tasks[key]=value;localStorage.setItem(CAREER_TASK_KEY,JSON.stringify(tasks))}
function unique(items){return [...new Set(items.filter(Boolean))]}

function authView(mode='login'){
  const register=mode==='register';
  app.innerHTML=`<div class="auth"><section class="auth-hero"><div class="brand"><img src="images/logo.svg" alt=""><span>CoursePilot</span></div><div class="hero-copy"><span class="eyebrow">Full-stack learning platform</span><h1>Learn practical skills. Prove what you can build.</h1><p>Join free career-focused courses, complete guided lessons, pass skill checks and earn shareable course certificates.</p><div class="hero-stats"><div class="hero-stat"><strong>30+</strong><span>Career courses</span></div><div class="hero-stat"><strong>100%</strong><span>Free enrollment</span></div><div class="hero-stat"><strong>1 click</strong><span>Certificate printing</span></div></div></div><small>Built as a portfolio-ready full-stack LMS.</small></section><section class="auth-panel"><div class="auth-card"><a class="auth-back" href="#home">← Back to website</a><h2>${register?'Create your account':'Welcome back'}</h2><p>${register?'Start learning for free.':'Continue your learning journey.'}</p><div id="authError"></div><form id="authForm">${register?`<div class="field"><label>Full name</label><input id="name" autocomplete="name" placeholder="Your full name" required></div>`:''}<div class="field"><label>Email address</label><input id="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field"><label>Password</label><input id="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'8+ characters, uppercase + number':'Enter your password'}" required></div><button class="btn btn-primary btn-block">${register?'Create free account':'Sign in'}</button></form><div class="auth-switch">${register?'Already have an account?':'New to CoursePilot?'} <button id="switchAuth">${register?'Sign in':'Create account'}</button></div>${!register?`<div class="demo-box"><strong>Demo accounts</strong><div class="demo-row"><div><b>Student</b><small>student@coursepilot.dev · Student123</small></div><button class="btn btn-soft btn-sm demo" data-email="student@coursepilot.dev" data-pass="Student123">Use</button></div><div class="demo-row"><div><b>Instructor</b><small>instructor@coursepilot.dev · Faculty123</small></div><button class="btn btn-soft btn-sm demo" data-email="instructor@coursepilot.dev" data-pass="Faculty123">Use</button></div></div>`:''}</div></section></div>`;
  document.getElementById('switchAuth').onclick=()=>{location.hash=register?'login':'register'};
  const emailEl=document.getElementById('email'), passwordEl=document.getElementById('password'), form=document.getElementById('authForm');
  document.querySelectorAll('.demo').forEach(b=>b.onclick=()=>{emailEl.value=b.dataset.email;passwordEl.value=b.dataset.pass});
  form.onsubmit=async e=>{e.preventDefault();const error=document.getElementById('authError');error.innerHTML='';try{const payload={email:emailEl.value,password:passwordEl.value,...(register?{name:document.getElementById('name').value}:{})};const data=await api(`/auth/${register?'register':'login'}`,{method:'POST',body:JSON.stringify(payload)});setToken(data.token);me=data.user;location.hash='dashboard'}catch(err){error.innerHTML=`<div class="error">${esc(err.message)}</div>`}};
}
function navItems(){const base=[['dashboard','home','Dashboard'],['catalog','book','Explore courses'],['my-courses','grid','My learning'],['career','career','Career Center'],['certificates','award','Certificates']];if(me?.role==='instructor'||me?.role==='admin')base.push(['instructor','trend','Instructor']);return base}
function shell(title,subtitle,content,action=''){
  const current=route().split('/')[0];
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a href="#dashboard" class="brand"><img src="images/logo.svg" alt=""><span>CoursePilot</span></a><div class="nav-label">Learning</div>${navItems().map(n=>`<a class="nav-link ${current===n[0]?'active':''}" href="#${n[0]}">${icon(n[1])}<span>${n[2]}</span></a>`).join('')}<div class="sidebar-fill"></div><div class="sidebar-user"><strong>${esc(me?.name||'User')}</strong><small>${esc(me?.role||'student')}</small></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" id="mobileMenu">${icon('menu')}</button><div class="top-search">${icon('search')}<input id="globalSearch" placeholder="Search courses..."></div><div class="top-actions"><span class="role-name"><b>${esc(me?.name||'')}</b></span><div class="avatar">${initials(me?.name)}</div><button class="btn btn-outline btn-sm" id="logoutBtn">${icon('logout')}</button></div></header><div class="content"><div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>${content}</div></main><nav class="mobile-bottom">${navItems().slice(0,4).map(n=>`<a href="#${n[0]}" class="${current===n[0]?'active':''}">${icon(n[1])}<span>${n[2].replace('Explore ','')}</span></a>`).join('')}</nav></div>`;
  document.getElementById('logoutBtn').onclick=logout;
  document.getElementById('globalSearch').onkeydown=e=>{if(e.key==='Enter'){location.hash=`catalog?q=${encodeURIComponent(document.getElementById('globalSearch').value)}`}};
  document.getElementById('mobileMenu').onclick=()=>{const m=modal('Navigation',`<div class="list">${navItems().map(n=>`<a class="activity" href="#${n[0]}" onclick="this.closest('.modal-backdrop').remove()"><div class="activity-icon">${icon(n[1])}</div><div><strong>${n[2]}</strong></div></a>`).join('')}</div>`);};
}
async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}setToken('');me=null;location.hash='login'}
function courseCard(c){return `<article class="course-card"><img class="course-cover" src="${esc(c.cover)}" alt=""><div class="course-body"><div class="course-topline"><span class="course-category">${esc(c.category)}</span><span class="pill ${c.enrolled?'success':''}">${c.enrolled?'Enrolled':money(c.price)}</span></div><div class="course-title">${esc(c.title)}</div><div class="course-desc">${esc(c.description)}</div><div class="course-meta"><span>${esc(c.level)}</span><span>•</span><span>${esc(c.duration)}</span><span>•</span><span>★ ${c.rating}</span></div>${c.enrolled?`<div class="progress-row"><div class="progress"><i style="width:${c.progress}%"></i></div><span>${c.progress}%</span></div>`:''}<div class="course-actions"><a class="btn ${c.enrolled?'btn-primary':'btn-outline'}" href="#course/${c.id}">${c.enrolled?'Continue':'View course'}</a></div></div></article>`}
async function dashboard(){const data=await api('/dashboard');const cards=data.courses.length?data.courses.slice(0,3).map(courseCard).join(''):`<div class="empty"><h3>No courses yet</h3><p>Explore the catalog and enroll in your first free course.</p><a class="btn btn-primary" href="#catalog">Browse courses</a></div>`;const activity=data.recentActivity.length?data.recentActivity.map(a=>`<div class="activity"><div class="activity-icon">${icon(a.type==='certificate'?'award':a.type==='quiz'?'quiz':'check')}</div><div><strong>${esc(a.text)}</strong><small>${date(a.at)}</small></div></div>`).join(''):`<div class="empty">Your learning activity will appear here.</div>`;shell('Learning dashboard','Track courses, progress and achievements.',`<div class="grid grid-4"><div class="stat-card"><div class="stat-icon">${icon('book')}</div><strong>${data.stats.enrolled}</strong><span>Enrolled courses</span></div><div class="stat-card"><div class="stat-icon">${icon('trend')}</div><strong>${data.stats.avgProgress}%</strong><span>Average progress</span></div><div class="stat-card"><div class="stat-icon">${icon('check')}</div><strong>${data.stats.completed}</strong><span>Courses completed</span></div><div class="stat-card"><div class="stat-icon">${icon('award')}</div><strong>${data.stats.certificates}</strong><span>Certificates earned</span></div></div><h2 class="section-title">Continue learning</h2><div class="course-grid">${cards}</div><div class="grid grid-2" style="margin-top:24px"><div class="card"><div class="card-head"><h2>Recent activity</h2></div><div class="list">${activity}</div></div><div class="card"><div class="card-head"><h2>How certificates work</h2></div><div class="notice">Complete all lessons and score at least 70% on the course quiz. Your certificate unlocks automatically.</div><p style="color:var(--muted)">Every certificate includes your name, course title, issue date and a unique certificate ID.</p><a class="btn btn-outline" href="#certificates">View certificates</a></div></div>`)}
async function catalog(){const params=new URLSearchParams(route().split('?')[1]||'');const q=params.get('q')||'';const data=await api(`/courses${q?`?search=${encodeURIComponent(q)}`:''}`);lastCourses=data.courses;shell('Explore courses','All courses are free to enroll in.',`<div class="catalog-toolbar"><input id="catalogSearch" value="${esc(q)}" placeholder="Search title, skill or topic"><select id="categoryFilter"><option value="">All categories</option>${[...new Set(data.courses.map(c=>c.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="levelFilter"><option value="">All levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div id="catalogGrid" class="course-grid">${data.courses.map(courseCard).join('')||'<div class="empty">No matching courses found.</div>'}</div>`);const searchEl=document.getElementById('catalogSearch'), catEl=document.getElementById('categoryFilter'), levelEl=document.getElementById('levelFilter'), gridEl=document.getElementById('catalogGrid');const render=()=>{const term=searchEl.value.toLowerCase();const cat=catEl.value;const level=levelEl.value;const filtered=lastCourses.filter(c=>(!term||`${c.title} ${c.description} ${c.skills.join(' ')}`.toLowerCase().includes(term))&&(!cat||c.category===cat)&&(!level||c.level===level));gridEl.innerHTML=filtered.map(courseCard).join('')||'<div class="empty">No matching courses found.</div>'};searchEl.oninput=render;catEl.onchange=render;levelEl.onchange=render}
async function myCourses(){const data=await api('/dashboard');shell('My learning','Pick up where you left off.',`<div class="course-grid">${data.courses.map(courseCard).join('')||'<div class="empty"><h3>You are not enrolled yet</h3><p>Choose a free course to start learning.</p><a class="btn btn-primary" href="#catalog">Explore courses</a></div>'}</div>`)}
async function coursePage(id){
  const data=await api(`/courses/${id}`);const c=data.course;const career=careerProfile(c);
  const lessons=c.lessons.map((l,i)=>`<div class="lesson ${c.completedLessonIds?.includes(l.id)?'done':''}"><div class="lesson-head"><div class="lesson-index">${c.completedLessonIds?.includes(l.id)?icon('check'):i+1}</div><div class="lesson-main"><strong>${esc(l.title)}</strong><small>${esc(l.duration)}</small></div>${c.enrolled&&!c.completedLessonIds?.includes(l.id)?`<button class="btn btn-soft btn-sm completeLesson" data-id="${l.id}">Mark complete</button>`:''}</div><div class="lesson-content">${esc(l.content)}</div></div>`).join('');
  const quizPassed=(c.quizBestScore??0)>=c.passPercent;
  const completion=`<section class="career-course-block"><div class="career-course-head"><div><span class="career-eyebrow">Course → career path</span><h2>What this course can lead to</h2><p>Use the course as one part of a job-ready portfolio—not as a job guarantee.</p></div><a class="btn btn-outline btn-sm" href="#career">Open Career Center</a></div><div class="career-course-grid"><article class="career-value-card"><div class="career-card-icon">${icon('target')}</div><h3>Course value</h3><p>${esc(career.value)}</p><div class="career-mini-label">Target roles</div><div class="role-chip-row">${career.roles.map(r=>`<span>${esc(r)}</span>`).join('')}</div></article><article class="career-value-card"><div class="career-card-icon">${icon('grid')}</div><h3>Portfolio project</h3><p>${esc(career.project)}</p><div class="career-mini-label">Show employers</div><p class="career-small">Include a README, screenshots, live/demo link where possible, technologies used and the problem you solved.</p></article><article class="career-value-card completion-card"><div class="career-card-icon">${icon('award')}</div><h3>How to complete</h3><div class="completion-list"><div class="${c.progress===100?'is-done':''}"><span>${c.progress===100?'✓':'1'}</span><p><b>Finish all lessons</b><small>${c.enrolled?`${c.progress}% complete`:'Enroll to start tracking'}</small></p></div><div class="${quizPassed?'is-done':''}"><span>${quizPassed?'✓':'2'}</span><p><b>Pass the skill check</b><small>Required score: ${c.passPercent}%${c.quizBestScore!=null?` · Best: ${c.quizBestScore}%`:''}</small></p></div><div class="${c.certificateIssuedAt?'is-done':''}"><span>${c.certificateIssuedAt?'✓':'3'}</span><p><b>Unlock certificate</b><small>${c.certificateIssuedAt?'Certificate earned':'Lessons + passing quiz required'}</small></p></div></div></article></div><div class="course-employers"><div><strong>Example employers to research for related roles</strong><small>Company names are examples only; there is no affiliation or employment guarantee.</small></div><div>${CAREER_COMPANIES.slice(0,6).map(x=>`<span>${x}</span>`).join('')}</div></div></section>`;
  const quiz=c.enrolled?`<div class="card" style="margin-top:18px"><div class="card-head"><div><h2>Final skill check</h2><small>Pass mark: ${c.passPercent}% · Best score: ${c.quizBestScore??'Not attempted'}${c.quizBestScore!=null?'%':''}</small></div>${icon('quiz')}</div><form id="quizForm">${(c.quiz||[]).map((q,idx)=>`<div class="quiz-question"><strong>${idx+1}. ${esc(q.question)}</strong>${q.options.map((o,oi)=>`<label class="quiz-option"><input type="radio" name="${q.id}" value="${oi}"><span>${esc(o)}</span></label>`).join('')}</div>`).join('')}<button class="btn btn-primary">Submit quiz</button><div id="quizResult"></div></form></div>`:'';
  const action=c.enrolled?'':`<button class="btn btn-primary" id="enrollBtn">Enroll free</button>`;
  shell(c.title,`${c.category} · ${c.level} · ${c.duration}`,`<section class="course-hero"><img src="${esc(c.cover)}" alt=""><div class="course-hero-content"><span class="pill">${esc(c.category)}</span><h1>${esc(c.title)}</h1><p>${esc(c.description)}</p><div class="skills">${c.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div><p><b>${c.instructor}</b> · ★ ${c.rating} · ${c.students.toLocaleString()} learners</p>${c.enrolled?`<div class="progress-row" style="max-width:440px"><div class="progress"><i style="width:${c.progress}%"></i></div><span style="color:#fff">${c.progress}%</span></div>`:''}</div></section>${!c.enrolled?'<div class="notice">Enroll for free to track progress, take the quiz and earn a certificate.</div>':''}${completion}<h2 class="section-title">Course lessons</h2><div class="list">${lessons}</div>${quiz}`,action);
  if(!c.enrolled){document.getElementById('enrollBtn').onclick=async()=>{try{await api(`/courses/${c.id}/enroll`,{method:'POST'});toast('Enrollment successful');coursePage(c.id)}catch(e){toast(e.message)}}}
  document.querySelectorAll('.completeLesson').forEach(b=>b.onclick=async()=>{try{await api(`/courses/${c.id}/lessons/${b.dataset.id}/complete`,{method:'POST'});toast('Lesson completed');coursePage(c.id)}catch(e){toast(e.message)}});
  if(c.enrolled&&document.getElementById('quizForm')){const quizFormEl=document.getElementById('quizForm');quizFormEl.onsubmit=async e=>{e.preventDefault();const answers={};(c.quiz||[]).forEach(q=>{const v=new FormData(quizFormEl).get(q.id);if(v!==null)answers[q.id]=Number(v)});try{const r=await api(`/courses/${c.id}/quiz`,{method:'POST',body:JSON.stringify({answers})});document.getElementById('quizResult').innerHTML=`<div class="quiz-result"><b>${r.passed?'Passed':'Keep learning'} — ${r.percent}%</b><div>You answered ${r.score} of ${r.total} correctly.${r.certificateIssuedAt?' Your certificate is now unlocked!':''}</div>${r.certificateIssuedAt?'<a class="btn btn-primary btn-sm" style="margin-top:10px" href="#certificates">View certificate</a>':''}</div>`;toast(r.passed?'Quiz passed':'Quiz submitted')}catch(err){toast(err.message)}}}
}

async function careerCenter(){
  const [dash,catalogData]=await Promise.all([api('/dashboard'),api('/courses')]);
  const enrolled=dash.courses||[], tasks=careerTasks();
  const hasEnrollment=enrolled.length>0, hasCompletion=dash.stats.completed>0, hasCertificate=dash.stats.certificates>0;
  const manual=[['portfolio','Build one portfolio project'],['profile','Update CV / LinkedIn / portfolio'],['interview','Practice technical interview questions'],['applications','Apply to at least 5 relevant roles']];
  const completedCount=[hasEnrollment,hasCompletion,hasCertificate,...manual.map(([k])=>!!tasks[k])].filter(Boolean).length;
  const prep=Math.round(completedCount/7*100);
  const sourceCourses=enrolled.length?enrolled:(catalogData.courses||[]).slice(0,6);
  const roles=unique(sourceCourses.flatMap(c=>careerProfile(c).roles)).slice(0,6);
  const skills=unique(sourceCourses.flatMap(c=>c.skills||[])).slice(0,14);
  const featured=sourceCourses.slice(0,3).map(c=>{const cp=careerProfile(c);return `<article class="career-role-card"><span class="career-role-course">${esc(c.title)}</span><h3>${esc(cp.roles[0])}</h3><p>${esc(cp.value)}</p><div class="role-chip-row">${cp.roles.slice(1).map(r=>`<span>${esc(r)}</span>`).join('')}</div><a href="#course/${c.id}">View course path →</a></article>`}).join('');
  const roadmap=`<div class="career-roadmap"><div class="roadmap-item ${hasEnrollment?'done':''}"><span>${hasEnrollment?'✓':'1'}</span><div><b>Choose and enroll in a role-relevant course</b><small>${hasEnrollment?`${enrolled.length} course${enrolled.length===1?'':'s'} enrolled`:'Start with one focused learning path.'}</small></div></div><div class="roadmap-item ${hasCompletion?'done':''}"><span>${hasCompletion?'✓':'2'}</span><div><b>Complete the lessons and pass the assessment</b><small>${hasCompletion?`${dash.stats.completed} course${dash.stats.completed===1?'':'s'} completed`:'Aim for 100% lesson progress and the required quiz score.'}</small></div></div><div class="roadmap-item ${hasCertificate?'done':''}"><span>${hasCertificate?'✓':'3'}</span><div><b>Earn and add your certificate</b><small>${hasCertificate?`${dash.stats.certificates} certificate${dash.stats.certificates===1?'':'s'} earned`:'Use it as supporting evidence on your CV, LinkedIn and portfolio.'}</small></div></div>${manual.map(([key,label],i)=>`<label class="roadmap-item manual ${tasks[key]?'done':''}"><input class="careerTask" type="checkbox" data-key="${key}" ${tasks[key]?'checked':''}><span>${tasks[key]?'✓':i+4}</span><div><b>${label}</b><small>${key==='portfolio'?'Show what you can actually build with the course skills.':key==='profile'?'Make your skills, projects and certificate easy for recruiters to find.':key==='interview'?'Practice explaining your code, decisions and problem-solving.':'Track applications and tailor your CV to each role.'}</small></div></label>`).join('')}</div>`;
  shell('Career Center','Turn course progress into a practical job-search plan.',`<section class="career-dashboard-hero"><div><span class="career-eyebrow">Career preparation</span><h2>From course completion to job applications.</h2><p>Use this roadmap to connect learning, certificates, portfolio evidence and interview preparation. The score tracks preparation steps only—it is not a prediction of hiring.</p><div class="career-skill-row">${skills.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Enroll in courses to build your skill profile.</span>'}</div></div><div class="readiness-ring" style="--score:${prep}"><div><strong>${prep}%</strong><span>plan complete</span></div></div></section><div class="career-stats grid grid-4"><div class="stat-card"><div class="stat-icon">${icon('book')}</div><strong>${enrolled.length}</strong><span>Courses in your plan</span></div><div class="stat-card"><div class="stat-icon">${icon('award')}</div><strong>${dash.stats.certificates}</strong><span>Certificates earned</span></div><div class="stat-card"><div class="stat-icon">${icon('target')}</div><strong>${roles.length}</strong><span>Suggested role types</span></div><div class="stat-card"><div class="stat-icon">${icon('trend')}</div><strong>${dash.stats.avgProgress}%</strong><span>Learning progress</span></div></div><div class="grid career-main-grid"><section class="card career-plan-card"><div class="card-head"><div><h2>Your job-preparation roadmap</h2><small>Complete the automatic learning steps and tick off the career tasks.</small></div></div>${roadmap}</section><section class="card certificate-value-panel"><div class="card-head"><h2>What the certificate is worth</h2>${icon('award')}</div><p><b>It proves course completion and assessment performance.</b> It can strengthen a CV or portfolio when paired with projects, GitHub work and interview-ready skills.</p><div class="certificate-use-list"><span>✓ Add it to your CV under Courses / Certifications</span><span>✓ Add the course skills to your portfolio project</span><span>✓ Explain what you built and learned in interviews</span><span>✓ Share the certificate ID as supporting evidence</span></div><div class="career-note">A CoursePilot certificate is a course-completion credential, not a university degree, professional license or promise of employment.</div><a class="btn btn-outline btn-sm" href="#certificates">View my certificates</a></section></div><h2 class="section-title">Roles connected to your learning</h2><div class="career-role-grid">${featured||'<div class="empty">Enroll in a course to get personalized role suggestions.</div>'}</div><section class="career-employer-panel"><div><span class="career-eyebrow">Where to research opportunities</span><h2>Example global employers</h2><p>Search these companies—and similar employers—for openings that match your role, location, experience and work-authorization requirements.</p></div><div class="career-company-grid">${CAREER_COMPANIES.map((x,i)=>`<span><b>${x.slice(0,2).toUpperCase()}</b>${x}</span>`).join('')}</div><small>Examples only. CoursePilot is not affiliated with or endorsed by these companies. Course completion does not guarantee a job or interview.</small></section>`);
  document.querySelectorAll('.careerTask').forEach(box=>box.onchange=()=>{setCareerTask(box.dataset.key,box.checked);careerCenter()});
}

async function certificates(){const data=await api('/certificates');shell('Certificates','Your CoursePilot learning achievements and proof of completion.',`<div class="certificate-value-banner"><div class="career-card-icon">${icon('award')}</div><div><h2>Use certificates as supporting proof—not as a job guarantee.</h2><p>Add them to your CV, LinkedIn and portfolio, then pair them with projects that show what you can build. Employers usually evaluate skills, experience, projects and interviews together.</p></div><a class="btn btn-outline btn-sm" href="#career">Career Center</a></div><div class="certificate-grid">${data.certificates.map(c=>`<article class="certificate-card"><div class="certificate-preview" id="cert-${c.courseId}"><small>COURSEPILOT LEARNING</small><h2>Certificate of Completion</h2><p>This certifies that</p><h3>${esc(c.studentName)}</h3><p>has successfully completed</p><h3 style="font-size:20px">${esc(c.courseTitle)}</h3><div class="cert-meta"><span>Issued ${date(c.issuedAt)}</span><span>ID ${esc(c.certificateId)}</span></div></div><button class="btn btn-primary btn-block no-print printCert" data-course="${c.courseId}" style="margin-top:12px">Print / Save as PDF</button></article>`).join('')||'<div class="empty"><h3>No certificates yet</h3><p>Complete all lessons and pass a course quiz to unlock your first certificate.</p><a class="btn btn-primary" href="#my-courses">Continue learning</a></div>'}</div>`);document.querySelectorAll('.printCert').forEach(b=>b.onclick=()=>{document.querySelectorAll('.certificate-card').forEach(x=>x.classList.remove('print-certificate'));b.closest('.certificate-card').classList.add('print-certificate');window.print()})}
async function instructor(){const data=await api('/instructor/dashboard');shell('Instructor workspace','Manage courses and monitor learner activity.',`<div class="grid grid-4"><div class="stat-card"><div class="stat-icon">${icon('book')}</div><strong>${data.stats.courses}</strong><span>Published courses</span></div><div class="stat-card"><div class="stat-icon">${icon('user')}</div><strong>${data.stats.learners}</strong><span>Unique learners</span></div><div class="stat-card"><div class="stat-icon">${icon('grid')}</div><strong>${data.stats.enrollments}</strong><span>Total enrollments</span></div><div class="stat-card"><div class="stat-icon">${icon('award')}</div><strong>${data.stats.certificates}</strong><span>Certificates earned</span></div></div><div class="card" style="margin-top:20px"><div class="card-head"><h2>Your courses</h2><button class="btn btn-primary btn-sm" id="newCourse">${icon('plus')} New course</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Course</th><th>Level</th><th>Lessons</th><th>Enrollments</th><th></th></tr></thead><tbody>${data.courses.map(c=>`<tr><td><b>${esc(c.title)}</b><br><small>${esc(c.category)}</small></td><td>${esc(c.level)}</td><td>${c.lessons.length}</td><td>${c.enrollments}</td><td><button class="btn btn-outline btn-sm addLesson" data-id="${c.id}">Add lesson</button></td></tr>`).join('')}</tbody></table></div></div>`);document.getElementById('newCourse').onclick=()=>courseModal();document.querySelectorAll('.addLesson').forEach(b=>b.onclick=()=>lessonModal(b.dataset.id))}
function courseModal(){const d=modal('Create a new course',`<form id="newCourseForm"><div class="form-grid"><div class="field full"><label>Course title</label><input id="ncTitle" required></div><div class="field"><label>Category</label><select id="ncCategory"><option>Development</option><option>Frontend</option><option>Backend</option><option>AI & Automation</option><option>Developer Tools</option><option>Software Engineering</option><option>Cloud &amp; DevOps</option><option>API &amp; Integration</option><option>Computer Science</option><option>Databases</option><option>AI &amp; Robotics</option></select></div><div class="field"><label>Level</label><select id="ncLevel"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="field full"><label>Description</label><textarea id="ncDescription" required placeholder="Describe what learners will build and learn..."></textarea></div><div class="field"><label>Duration</label><input id="ncDuration" value="6 weeks"></div></div><button class="btn btn-primary">Publish course</button></form>`);document.getElementById('newCourseForm').onsubmit=async e=>{e.preventDefault();try{await api('/instructor/courses',{method:'POST',body:JSON.stringify({title:document.getElementById('ncTitle').value,category:document.getElementById('ncCategory').value,level:document.getElementById('ncLevel').value,description:document.getElementById('ncDescription').value,duration:document.getElementById('ncDuration').value})});d.remove();toast('Course published');instructor()}catch(err){toast(err.message)}}}
function lessonModal(courseId){const d=modal('Add lesson',`<form id="lessonForm"><div class="field"><label>Lesson title</label><input id="lessonTitle" required></div><div class="field"><label>Duration</label><input id="lessonDuration" value="15 min"></div><div class="field"><label>Lesson content</label><textarea id="lessonContent" required placeholder="Write the lesson summary or learning material..."></textarea></div><button class="btn btn-primary">Add lesson</button></form>`);document.getElementById('lessonForm').onsubmit=async e=>{e.preventDefault();try{await api(`/instructor/courses/${courseId}/lessons`,{method:'POST',body:JSON.stringify({title:document.getElementById('lessonTitle').value,duration:document.getElementById('lessonDuration').value,content:document.getElementById('lessonContent').value})});d.remove();toast('Lesson added');instructor()}catch(err){toast(err.message)}}}
async function render(){const r=route();if(r==='home')return homePage();if(r==='login'){authView('login');return}if(r==='register'){authView('register');return}if(!token){location.hash='login';return}if(!me)await loadMe();if(!me){authView('login');return}try{if(r==='dashboard')return dashboard();if(r.startsWith('catalog'))return catalog();if(r==='my-courses')return myCourses();if(r==='career')return careerCenter();if(r.startsWith('course/'))return coursePage(r.split('/')[1]);if(r==='certificates')return certificates();if(r==='instructor')return instructor();location.hash='home'}catch(e){shell('Something went wrong',e.message,`<div class="error">${esc(e.message)}</div><a class="btn btn-primary" href="#dashboard">Back to dashboard</a>`)}}
window.addEventListener('hashchange',render);render();
